// Matches http:// or https:// URLs. The scheme must be exactly "http" or
// "https" (a misspelled prefix like "htp://" will not match), and the URL runs
// up to the next whitespace or quote/angle character.
const URL_REGEX = /https?:\/\/[^\s<>"']+/g;

const TRAILING_PUNCTUATION = new Set([".", ",", ";", ":", "!", "?"]);

/**
 * Splits trailing punctuation and unbalanced closing brackets off the end of a
 * matched URL so that things like "(https://example.com)" or "https://x.com."
 * linkify only the URL itself, leaving the punctuation as plain text.
 */
const splitTrailing = (match: string): { url: string; trailing: string } => {
  let url = match;
  let trailing = "";

  const countChar = (value: string, char: string) =>
    value.split(char).length - 1;

  while (url.length > 0) {
    const last = url[url.length - 1];

    if (TRAILING_PUNCTUATION.has(last)) {
      trailing = last + trailing;
      url = url.slice(0, -1);
      continue;
    }

    if (last === ")" && countChar(url, ")") > countChar(url, "(")) {
      trailing = last + trailing;
      url = url.slice(0, -1);
      continue;
    }

    if (last === "]" && countChar(url, "]") > countChar(url, "[")) {
      trailing = last + trailing;
      url = url.slice(0, -1);
      continue;
    }

    if (last === "}" && countChar(url, "}") > countChar(url, "{")) {
      trailing = last + trailing;
      url = url.slice(0, -1);
      continue;
    }

    break;
  }

  return { url, trailing };
};

const handleAnchorClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
  event.stopPropagation();
};

/**
 * Converts a plain string into an array of React nodes, replacing every
 * http/https URL with an anchor element. Returns the original string unchanged
 * when it contains no linkifiable URL.
 */
const linkifyString = (
  value: string,
  keyPrefix: string,
): React.ReactNode => {
  URL_REGEX.lastIndex = 0;

  const nodes: React.ReactNode[] = [];
  let lastIndex = 0;
  let matchCount = 0;
  let match: RegExpExecArray | null;

  while ((match = URL_REGEX.exec(value)) !== null) {
    const { url, trailing } = splitTrailing(match[0]);

    // A match that collapses to just punctuation can be ignored.
    if (!url) {
      continue;
    }

    const start = match.index;
    if (start > lastIndex) {
      nodes.push(value.slice(lastIndex, start));
    }

    nodes.push(
      <a
        key={`${keyPrefix}-link-${matchCount}`}
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className="break-all text-blue-600 underline hover:text-blue-800"
        onClick={handleAnchorClick}
      >
        {url}
      </a>,
    );

    if (trailing) {
      nodes.push(trailing);
    }

    lastIndex = start + url.length + trailing.length;
    matchCount += 1;
  }

  if (matchCount === 0) {
    // No URLs found — render the string exactly as provided (no wrapper).
    return value;
  }

  if (lastIndex < value.length) {
    nodes.push(value.slice(lastIndex));
  }

  return nodes;
};

const renderNode = (node: React.ReactNode, keyPrefix: string): React.ReactNode => {
  if (node === null || node === undefined || typeof node === "boolean") {
    return null;
  }

  if (typeof node === "string") {
    return linkifyString(node, keyPrefix);
  }

  if (typeof node === "number") {
    // Render the numeric value as text; numbers never contain URLs.
    return String(node);
  }

  if (Array.isArray(node)) {
    return node.map((child, index) => (
      <React.Fragment key={`${keyPrefix}-${index}`}>
        {renderNode(child, `${keyPrefix}-${index}`)}
      </React.Fragment>
    ));
  }

  // Any other React node (elements, portals, etc.) is rendered as-is.
  return node;
};

